function renderGroups(){searchWrap.style.display="none";title.textContent="القروبات";subtitle.textContent="قروبات المجتمع ومساحاتك المحفوظة.";content.className="feature-grid";const saved=JSON.parse(localStorage.getItem("mld_groups")||"[]");content.innerHTML='<article class="feature-card"><div class="feature-icon">👥</div><h3>إنشاء قروب</h3><input id="group-name" class="full" maxlength="40" placeholder="اسم القروب"><input id="group-desc" class="full" maxlength="120" placeholder="وصف القروب"><button class="primary wide" id="group-add">إنشاء</button></article><article class="feature-card"><h3>قروباتي</h3><div id="groups-list" class="groups-list">'+(saved.length?saved.map((g,i)=>'<div class="group-item"><span><b>'+esc(g.name)+'</b><small>'+esc(g.desc||"بدون وصف")+'</small></span><button data-group="'+i+'">حذف</button></div>').join(""):'<p class="muted">لا توجد قروبات محفوظة.</p>')+'</div></article>';$("#group-add").onclick=()=>{const n=$("#group-name").value.trim(),d=$("#group-desc").value.trim();if(!n)return;const a=JSON.parse(localStorage.getItem("mld_groups")||"[]");a.push({name:n,desc:d});localStorage.setItem("mld_groups",JSON.stringify(a));renderGroups()};document.querySelectorAll("[data-group]").forEach(b=>b.onclick=()=>{const a=JSON.parse(localStorage.getItem("mld_groups")||"[]");a.splice(Number(b.dataset.group),1);localStorage.setItem("mld_groups",JSON.stringify(a));renderGroups()});setStatus("القروبات جاهزة")}
