const t=await fetch("/api/owner/tickets").then(r=>r.json()),a=await fetch("/api/owner/applications").then(r=>r.json());$("#owner-requests").innerHTML=(t.tickets||[]).map(x=>`<div class="log-item"><b>#${x.id} · ${esc(x.subject)}</b><span>${esc(x.username)} · ${esc(x.discord_username)} · ${esc(x.status)}</span><small>${new Date(x.created_at).toLocaleString("ar-SA")}</small><button data-open-admin-ticket="${x.id}">المحادثة</button><button data-ticket-status="${x.id}" data-status="closed">إغلاق</button><button data-ticket-status="${x.id}" data-status="open">فتح</button></div>`).join("")||"<p class='muted'>لا توجد تيكات.</p>";document.querySelectorAll("[data-ticket-status]").forEach(btn=>btn.onclick=async()=>{await fetch("/api/owner/tickets/"+btn.dataset.ticketStatus+"/status",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({status:btn.dataset.status})});ownerPanel()});document.querySelectorAll("[data-open-admin-ticket]").forEach(btn=>btn.onclick=()=>openTicket(Number(btn.dataset.openAdminTicket)));
